using RAWSelectionAssistant.Core.Services.FreeCanvas;
namespace RAWSelectionAssistant.Tests;
[TestClass]public sealed class CanvasProductClosureTests
{
 [TestMethod]public void OneGestureUndoLockedTransformsAndViewIndependentDocumentSize(){var editor=new CanvasEditor(new(){PixelWidth=640,PixelHeight=480});editor.Add([new(){Name="image",Width=100,Height=80}]);var id=editor.Selected[0].ObjectId;editor.BeginGesture();for(int i=0;i<20;i++)editor.Move(1,2);editor.Rotate(30);editor.Resize(160,70);editor.EndGesture();Assert.AreEqual(20,editor.Selected[0].X);editor.Undo();Assert.AreEqual(0,editor.Document.Objects[0].X);Assert.AreEqual(100,editor.Document.Objects[0].Width);editor.Redo();editor.Select(id);editor.SetLocked(true);var frozen=editor.Document;editor.Move(10,10);editor.Scale(2);editor.Resize(200,300);editor.Rotate(20);editor.Remove();Assert.AreSame(frozen,editor.Document);editor.SetVisible(false);Assert.AreSame(frozen,editor.Document);editor.SetLocked(false);editor.SetVisible(false);Assert.IsTrue(editor.Document.Objects[0].Hidden);editor.SetVisible(true);Assert.AreEqual(640,editor.Document.PixelWidth);}
 [TestMethod]public void BrushLayerIsSameUndoModelAndPersistsOneStroke(){var editor=new CanvasEditor(new(){PixelWidth=200,PixelHeight=100});editor.AddBrushLayer();editor.AddBrushStroke(new([new(.1,.5),new(.9,.5)],"#FF4020",10,.5,.7));Assert.IsTrue(editor.Selected[0].IsBrush);Assert.IsFalse(editor.Selected[0].IsImage);editor.Undo();Assert.AreEqual(0,editor.Document.Objects[0].BrushStrokes!.Count);editor.Redo();Assert.AreEqual(1,editor.Document.Objects[0].BrushStrokes!.Count);editor.SetLocked(true);Assert.Throws<InvalidOperationException>(()=>editor.AddBrushStroke(new([new(.5,.5)],"#FFFFFF",4,1,1)));}
}
